#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct N {
    int key;
    struct N *child;
} N;
int main(void)
{
    N child = {3, NULL};
    N *root = malloc(sizeof *root);
    if (!root) {
        return 1;
    }
    *root = (N){8, &child};
    N *saved = root->child;
    free(root);
    root = saved;
    printf("%d\n", root->key);
    return 0;
}

